descriptor.templateCss:
:host {
  display: block;
  width: 100%;
  height: 100%;
}

.message-composer {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  padding: 16px 18px 10px;
  color: var(--tb-primary-text-color, #202124);
  background: var(--tb-card-background-color, #ffffff);
}

.composer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 28px;
}

.composer-title {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  font-size: 16px;
  font-weight: 600;
}

.composer-title mat-icon {
  color: var(--tb-primary-500, #305680);
}

.composer-fields {
  display: grid;
  grid-template-columns: minmax(180px, 0.8fr) minmax(280px, 2fr) auto;
  align-items: center;
  gap: 12px;
  min-height: 58px;
}

.subject-field,
.body-field {
  width: 100%;
}

.send-button {
  min-width: 112px;
  height: 56px;
  min-height: 56px;
  align-self: start;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.status {
  flex: 0 0 auto;
  max-width: 55%;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.status-sending {
  color: #175cd3;
  background: #eff8ff;
}

.status-success {
  color: #027a48;
  background: #ecfdf3;
}

.status-error {
  color: #b42318;
  background: #fef3f2;
}

.composer-footer {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: -8px;
  color: var(--tb-secondary-text-color, #667085);
  font-size: 11px;
}

:host ::ng-deep .mat-mdc-form-field-subscript-wrapper {
  display: none;
}

@media (max-width: 600px) {
  .message-composer {
    justify-content: flex-start;
    gap: 10px;
    padding: 14px 12px 10px;
  }

  .composer-fields {
    grid-template-columns: minmax(0, 1fr) 96px;
    align-items: stretch;
    gap: 10px;
  }

  .subject-field {
    grid-column: 1;
    grid-row: 1;
  }

  .body-field {
    grid-column: 1 / -1;
    grid-row: 2;
  }

  .body-field textarea {
    min-height: 64px;
  }

  .send-button {
    grid-column: 2;
    grid-row: 1;
    width: 100%;
    min-width: 0;
  }

  .status {
    max-width: 45%;
  }
}

descriptor.controllerScript:
var statusTimer;

self.onInit = function() {
  var scope = self.ctx.$scope;

  scope.titleControl = scope.fb.control('');
  scope.bodyControl = scope.fb.control('');
  scope.executing = false;
  scope.statusText = '';
  scope.statusClass = '';

  scope.sendMessage = function() {
    var title = (scope.titleControl.value || '').trim();
    var body = (scope.bodyControl.value || '').trim();

    if (scope.executing || !body) {
      return;
    }

    if (!title) {
      title = 'ThingsBoard';
    }

    var payload = {
      kind: 'bikecomputer_notification',
      notify_title: title.substring(0, 64),
      notify_body: body.substring(0, 500),
      notify_request_id: Date.now().toString(36) + '-' +
        Math.random().toString(36).substring(2, 8)
    };

    setStatus('Sending...', 'status-sending', true);

    self.ctx.http.post('/api/rule-engine/', payload).subscribe(
      function() {
        scope.bodyControl.setValue('');
        setStatus('Sent', 'status-success', false);
        scheduleStatusClear();
      },
      function(error) {
        var message = 'Send failed';
        if (error && error.error && error.error.message) {
          message += ': ' + error.error.message;
        }
        setStatus(message, 'status-error', false);
      }
    );
  };

  self.ctx.detectChanges();
};

function setStatus(text, statusClass, executing) {
  var scope = self.ctx.$scope;
  scope.statusText = text;
  scope.statusClass = statusClass;
  scope.executing = executing;
  self.ctx.detectChanges();
}

function scheduleStatusClear() {
  if (statusTimer) {
    clearTimeout(statusTimer);
  }
  statusTimer = setTimeout(function() {
    setStatus('', '', false);
  }, 6000);
}

self.onDestroy = function() {
  if (statusTimer) {
    clearTimeout(statusTimer);
  }
};

self.typeParameters = function() {
  return {
    maxDatasources: 0,
    dataKeysOptional: true
  };
};
